/* app35: AI Team bridge (Command Deck org chart <-> this dashboard's workflows, pages and Handoff Board), Broker Bridge (Real Estate Broker Dashboard -> mortgage side), Brain 6D tools (recall commands, brain-ready exports, capture). */
const btLabel=k=>{for(const g of PAGES){const x=g[1].find(y=>y[0]===k);if(x)return x[1]}return k};
const btToday=()=>new Date().toISOString().slice(0,10);
const btAddD=(s,n)=>{const d=new Date(s+"T12:00:00");d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const btAddBiz=(s,n)=>{const d=new Date(s+"T12:00:00");let c=0;while(c<n){d.setDate(d.getDate()+1);if(d.getDay()%6)c++}return d.toISOString().slice(0,10)};
const btDiff=(a,b)=>Math.round((new Date(a+"T12:00:00")-new Date(b+"T12:00:00"))/864e5);
async function btSave(name,text,mime){const blob=new Blob([text],{type:mime||"text/plain"});try{const dl=window.claude?.use?await window.claude.use("downloads"):null;if(dl){await dl.save({filename:name,data:blob});toast("Saved "+name);return}}catch(e){if(e&&e.code==="declined")return toast("Download cancelled")}const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);toast("Downloaded "+name)}

/* ---------- AI Team model ---------- */
const aiExecOf=s=>s.t==="exec"?s.n:AI_SEATS.some(x=>x.t==="exec"&&x.n===s.b)?s.b:null;
const aiPages=s=>(AI_SEAT_PG[s.n]||AI_EXEC_PG[aiExecOf(s)]||AI_EXEC_PG[s.n]||"board").split(",").filter(k=>PAGE[k]);
const aiWfOwn=w=>{const r=AI_WF_OWN.find(x=>x[0].test(w.event));return r?{p:r[1],b:r[2],why:r[3]}:null};
const aiPB=s=>PB_WORKFLOWS.filter(w=>{const o=aiWfOwn(w);return o&&(o.p===s.n||o.b===s.n)}).map(w=>({w,role:aiWfOwn(w).p===s.n?"primary":"backup"}));
const aiLane=s=>s.t==="human"?"ISA / EA":(s.t==="twin"||s.t==="exec")?"Steven decision":"AI drafted";
const aiAgent=s=>AGENTS.find(a=>a.name===s.n||a.name.startsWith(s.n+" ·"));
const aiSeat=n=>AI_SEATS.find(s=>s.n===n);
const aiTeamOf=e=>AI_SEATS.filter(s=>s.t==="rep"&&s.b===e);
const aiPlay=s=>AI_PLAY[s.n]?{p:AI_PLAY[s.n],own:true}:AI_PLAY[aiExecOf(s)]?{p:AI_PLAY[aiExecOf(s)],own:false,from:aiExecOf(s)}:null;
const aiScripts=s=>{const c=AI_SCRIPT_CATS[s.n]||[];return typeof SCRIPTS==="undefined"?[]:SCRIPTS.filter(x=>c.includes(x.cat))};
const aiPlayHtml=s=>{const P=aiPlay(s),sc=aiScripts(s);if(!P&&!sc.length)return "";const L=(h,a)=>a&&a.length?`<b>${h}</b><ul style="margin:2px 0 6px 18px">${a.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:"";return `<details class="sm" style="margin-top:4px"><summary>Playbook${P&&!P.own?` (inherits ${esc(P.from)}'s team rules)`:""}${sc.length?` · ${sc.length} scripts`:""}</summary>${P?L("Daily",P.p.daily)+L("Weekly",P.p.weekly)+L("Measured by",P.p.kpi)+L("Never",P.p.never):""}${sc.length?`<b>Scripts this seat uses</b><div>${sc.slice(0,12).map(x=>`<a href="#scripts" class="tag" title="${esc(x.t)}">${esc(x.id)} ${esc(x.t.slice(0,40))}</a>`).join(" ")}</div>`:""}</details>`};
const aiOwnerOf=c=>{const m=(c.src||"").match(/^AI:(.+)$/);if(m)return m[1];const w=PB_WORKFLOWS.find(x=>x.id===c.src);if(w){const o=aiWfOwn(w);if(o)return o.p}if(c.src==="BRK")return /contingency|COE|Close of escrow|Appraisal|EMD/i.test(c.t)?"Carmen":/license|E&O/i.test(c.t)?"Clay":"Kenji";return c.owner==="Steven"?"Steve":c.owner==="ISA"?"ISA / EA (human)":(c.owner||"Unassigned")};
const aiCtx=()=>{const B=boardCards(),now=new Date();const open=B.filter(c=>c.lane!=="Done");const od=open.filter(c=>c.due&&new Date(c.due)<now);const L=store.get("ld_leads",[]);const unc=L.filter(l=>!l.contacted).length;return {open:open.length,od:od.length,unc,leads:L.length,odList:od.slice(0,5).map(c=>c.t)}};
function aiPrompt(s,task){const c=aiCtx(),pb=aiPB(s).map(x=>x.w.id+" "+x.w.name),sk=AI_SKILL[s.n];return `You are ${s.n}${s.a?" ("+s.a+")":""} — ${s.r}, reporting to ${s.b}.${sk?` (Claude skill: ${sk})`:""}
Working for Steven Shearrill (CA broker/MLO; licensed CA, IL, NV, FL, AZ). You draft; you never send, quote, commit rates or approve — anything licensed comes back as a decision packet for Steven.

TASK: ${task||"(describe the task)"}

CONTEXT FROM THE VANESSA DASHBOARD (${btToday()}):
- Handoff Board: ${c.open} open cards, ${c.od} overdue${c.odList.length?" ("+c.odList.join("; ")+")":""}
- Leads on the speed-to-lead clock: ${c.leads} total, ${c.unc} not yet marked contacted
${pb.length?"- Workflows you own here: "+pb.join("; ")+"\n":""}- Where to work in the dashboard: ${aiPages(s).map(btLabel).join(", ")}

Return: (1) the draft or answer, (2) what you assumed, (3) what Steven or the ISA/EA must decide or do, (4) the compliance flags (RESPA, TRID, VA, DRE advertising) if any.`}

PAGE.aiteam={html:()=>{const ex=AI_SEATS.filter(s=>s.t==="exec").length;return `<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><div class="row" style="flex-wrap:wrap"><div class="sp"><h3 style="margin:0">AI Team Bridge <span class="sub">${AI_SEATS.length} seats from the Command Deck org chart ↔ ${PB_WORKFLOWS.length} workflows · ${AGENTS.length} dashboard agents · Handoff Board</span></h3><p class="sm mut" style="margin:6px 0 0"><b>How this connects:</b> the org chart lives in the Command Deck (separate artifact, separate storage), so this page holds a <b>snapshot</b> of its seats (extracted ${"2026-10-22"}) and adds the ownership map: which seat owns which Pabbly workflow, which dashboard pages it works in, and which Handoff Board lane its output lands in. Dispatching creates a real Handoff Board card (and fires <code>task.delegated</code> to Pabbly if connected) and gives you a ready-to-paste prompt for that seat in Claude. Seats never send, quote or approve — they hand back decision packets.</p></div><a class="btn sm" target="_blank" rel="noopener" href="https://claude.ai/artifact/3jbdGMNFkGLEpJiZ3cTmZW">Open Command Deck ↗</a></div></div>${omTabs("aitab","ai","org",[]).wrap()}`},
mount(){const ctxLine=()=>{const c=aiCtx();return `<p class="sm mut">Live from this dashboard: <b>${c.open}</b> open Handoff cards · <b>${c.od}</b> overdue · <b>${c.unc}</b> leads not yet contacted</p>`};
const seatCard=s=>{const pb=aiPB(s),ag=aiAgent(s),pg=aiPages(s),sk=AI_SKILL[s.n];return `<div class="card ai-seat" data-n="${esc(s.n)}" data-b="${esc(s.b)}" style="padding:10px"><div class="row" style="flex-wrap:wrap"><b>${esc(s.n)}</b><span class="tag">${esc(s.t==="rep"?"team":s.t==="vrep"?"Vanessa's report":s.t)}</span>${sk?`<span class="tag">skill: ${esc(sk)}</span>`:""}${ag?`<span class="tag ok">dashboard agent #${ag.n}</span>`:""}<span class="sp"></span><button class="btn ghost sm ai-d" data-n="${esc(s.n)}" data-b="${esc(s.b)}">Dispatch…</button></div><div class="sm">${esc(s.r)}${s.a?` · <code>${esc(s.a)}</code>`:""}</div><div class="sm mut">Reports to ${esc(s.b)} · output lane: <b>${aiLane(s)}</b></div>${pb.length?`<div class="sm" style="margin-top:4px"><b>Owns:</b> ${pb.map(x=>`<span class="tag" title="${esc(x.w.name)} (${x.role})">${x.w.id}${x.role==="backup"?"·b":""}</span>`).join(" ")}</div>`:""}<div class="sm" style="margin-top:4px"><b>Works in:</b> ${pg.map(k=>`<a href="#${k}">${esc(btLabel(k))}</a>`).join(" · ")}</div>${aiPlayHtml(s)}</div>`};
const find=(n,b)=>AI_SEATS.find(s=>s.n===n&&s.b===b)||aiSeat(n);
const tabs=[
 ["org","Org map",()=>`<div class="card"><div class="row" style="flex-wrap:wrap"><input id="ai_q" placeholder="Find a seat, role, agent id or workflow (e.g. Denise, TRID, PB26, speed)…" style="max-width:420px"><span class="sp"></span>${ctxLine()}</div></div><div id="ai_org"></div>`,
  ()=>{const draw=()=>{const q=($("#ai_q").value||"").toLowerCase();const hit=s=>!q||[s.n,s.r,s.a,s.b,aiPB(s).map(x=>x.w.id+x.w.name).join(" "),aiPages(s).join(" ")].join(" ").toLowerCase().includes(q);const grp=(title,sub,list)=>{const l=list.filter(hit);return l.length?`<div class="card"><h4 style="margin:0 0 6px">${esc(title)} <span class="sub">${esc(sub||"")}</span> <span class="tag">${l.length}</span></h4><div class="grid g2">${l.map(seatCard).join("")}</div></div>`:""};
   const P=AI_SEATS.filter(s=>s.t==="twin"||s.t==="coo"||s.t==="human");let h=grp("Steve · Vanessa · ISA/EA","principal's digital twin, chief of staff, the human desk",P)+grp("Vanessa's direct reports","orchestration, dispatch, knowledge, briefs",AI_SEATS.filter(s=>s.t==="vrep"));
   AI_SEATS.filter(s=>s.t==="exec").forEach(e=>{h+=grp(e.n+" — "+e.r.replace(/ · .*/,""),aiTeamOf(e.n).length+" on the team",[e,...aiTeamOf(e.n)])});
   h+=grp("Mentors","outside voices — advise Steven, do not run workflows",AI_SEATS.filter(s=>s.t==="mentor"));$("#ai_org").innerHTML=h||'<div class="card sm mut">No seat matches.</div>';$$(".ai-d").forEach(b=>b.onclick=()=>{store.set("ai_pick",{n:b.dataset.n,b:b.dataset.b});location.hash="#aiteam";const t=$("#ai_tabs button[data-t=dispatch]");t&&t.click()})};
   $("#ai_q").oninput=draw;draw()}],
 ["wf","Workflow owners",()=>`<div class="card"><p class="sm">Every Pabbly workflow in the Workflow Hub has a <b>primary seat</b> (drafts and runs it) and a <b>backup</b>. Events fired from this dashboard land on the Handoff Board with the owner shown.</p><div style="overflow:auto;max-height:65vh"><table><thead><tr><th>ID</th><th>Workflow</th><th>Event</th><th>Primary seat</th><th>Backup</th><th>SLA</th><th>Why</th></tr></thead><tbody>${PB_WORKFLOWS.map(w=>{const o=aiWfOwn(w);return `<tr><td><b>${w.id}</b></td><td class="sm">${esc(w.name)}</td><td class="sm"><code>${w.event}</code></td><td>${o?`<b>${esc(o.p)}</b>`:'<span class="tag bad">unowned</span>'}</td><td class="sm">${o?esc(o.b):""}</td><td class="sm">${esc(w.sla||"")}</td><td class="sm mut">${o?esc(o.why):""}</td></tr>`}).join("")}</tbody></table></div></div>`,()=>{}],
 ["dispatch","Dispatch",()=>{const pick=store.get("ai_pick",{n:"Vanessa",b:"Steve"});return `<div class="card"><div class="grid g2"><div><label class="sm">Seat</label><select id="ai_s" style="width:100%">${AI_SEATS.map(s=>`<option value="${esc(s.n)}|${esc(s.b)}" ${s.n===pick.n&&s.b===pick.b?"selected":""}>${esc(s.n)} — ${esc(s.r.slice(0,50))}</option>`).join("")}</select><div class="row" style="margin-top:8px;flex-wrap:wrap"><select id="ai_tpl" style="flex:1;min-width:200px"><option value="">Quick task template…</option>${AI_TASK_TPL.map((t,i)=>`<option value="${i}">${esc(t[0])}: ${esc(t[1].replace("{client}","…").slice(0,70))}</option>`).join("")}</select><input id="ai_cl" placeholder="Client / file" style="max-width:150px"></div><label class="sm" style="margin-top:8px;display:block">Task</label><textarea id="ai_t" rows="4" style="width:100%" placeholder="e.g. Prep the Hernandez VA IRRRL file for processing and list outstanding conditions"></textarea><div class="row" style="margin-top:8px;flex-wrap:wrap"><label class="sm">Due</label><select id="ai_due"><option value="60">1 hour</option><option value="240">4 hours</option><option value="1440" selected>Tomorrow</option><option value="4320">3 days</option></select><label class="sm"><input type="checkbox" id="ai_hi"> High priority</label></div><div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn" id="ai_card">Add to Handoff Board</button><button class="btn ghost" id="ai_cp">Copy prompt for this seat</button></div><p class="sm mut">Adding a card fires <code>task.delegated</code> to Pabbly if you've connected it. Nothing is sent to the seat automatically — paste the prompt into Claude (or the Command Deck) where that seat runs.</p></div><div><label class="sm">Prompt preview</label><pre id="ai_pv" class="sm" style="white-space:pre-wrap;max-height:380px;overflow:auto;background:var(--panel2,#0001);padding:8px;border-radius:6px"></pre><div id="ai_info" class="sm"></div></div></div></div>`},
  ()=>{const cur=()=>{const [n,b]=$("#ai_s").value.split("|");return find(n,b)};const draw=()=>{const s=cur();$("#ai_pv").textContent=aiPrompt(s,$("#ai_t").value.trim());const pb=aiPB(s);$("#ai_info").innerHTML=`<b>${esc(s.n)}</b> · lane <b>${aiLane(s)}</b>${pb.length?" · owns "+pb.map(x=>x.w.id).join(", "):""}<br>Works in: ${aiPages(s).map(k=>`<a href="#${k}">${esc(btLabel(k))}</a>`).join(" · ")}`};
   $("#ai_s").onchange=draw;$("#ai_t").oninput=draw;draw();
   $("#ai_tpl").onchange=()=>{const t=AI_TASK_TPL[+$("#ai_tpl").value];if(!t)return;const s=aiSeat(t[0]);if(s)$("#ai_s").value=s.n+"|"+s.b;$("#ai_t").value=t[1].replace("{client}",$("#ai_cl").value.trim()||"[client]");draw()};
   $("#ai_cp").onclick=()=>copy(aiPrompt(cur(),$("#ai_t").value.trim()));
   $("#ai_card").onclick=()=>{const t=$("#ai_t").value.trim();if(!t)return toast("Describe the task first");const s=cur();boardAdd({t:`[${s.n}] ${t.slice(0,90)}`,detail:t,owner:s.n,lane:aiLane(s),due:new Date(Date.now()+(+$("#ai_due").value)*60000).toISOString(),pri:$("#ai_hi").checked?"high":"normal",src:"AI:"+s.n},true);toast(`Card added for ${s.n}`);$("#ai_t").value="";draw()}}],
 ["rhythm","Rhythm · escalation · HALT",()=>`<div class="grid g2"><div class="card"><h4>Daily operating rhythm</h4><table class="sm"><tbody>${AI_RHYTHM.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td><td class="mut">${esc(r[3])}</td></tr>`).join("")}</tbody></table></div><div class="card"><h4>HALT list — Steven only, never delegated</h4><ul class="sm" style="margin:4px 0 0 18px">${AI_HALT.map(h=>`<li>${esc(h)}</li>`).join("")}</ul><p class="sm mut">Every seat drafts, prepares and recommends. Anything here goes to the <b>Steven decision</b> lane.</p></div></div><div class="card"><h4>Escalation ladder</h4><input id="ai_esc_d" placeholder="What happened? Client / file and one line (used when you press Raise now)" style="width:100%;margin-bottom:6px"><table class="sm"><thead><tr><th>Trigger</th><th>Route</th><th>Within</th><th></th></tr></thead><tbody>${AI_ESCALATE.map((e,i)=>`<tr><td><b>${esc(e[0])}</b></td><td>${esc(e[1])}</td><td>${esc(e[2])}</td><td><button class="btn ghost sm ai-esc" data-i="${i}">Raise now</button></td></tr>`).join("")}</tbody></table></div>`,
  ()=>{$$(".ai-esc").forEach(b=>b.onclick=()=>{const e=AI_ESCALATE[+b.dataset.i];const d=$("#ai_esc_d").value.trim();boardAdd({t:`ESCALATION — ${e[0]}${d?": "+d:""}`,detail:`Route: ${e[1]}. Respond within: ${e[2]}.`,owner:e[1].split(/[ →]/)[0],lane:"Steven decision",pri:"high",due:new Date(Date.now()+(/Now|5 min/.test(e[2])?5:/1 hour/.test(e[2])?60:/4 hours/.test(e[2])?240:1440)*60000).toISOString(),src:"AI:"+e[1].split(/[ →]/)[0]},true);toast("Escalation card added")})}],
 ["load","Workload by seat",()=>{const B=boardCards().filter(c=>c.lane!=="Done"),now=new Date();const by={};B.forEach(c=>{const o=aiOwnerOf(c);(by[o]=by[o]||[]).push(c)});const rows=Object.entries(by).sort((a,b)=>b[1].length-a[1].length);return `<div class="card"><p class="sm">Open Handoff Board cards grouped by the seat that owns them (from the card's workflow, dispatch tag or owner). Use this to spot an overloaded seat or a lane that's stuck.</p>${rows.length?`<table><thead><tr><th>Seat</th><th>Open</th><th>Overdue</th><th>High priority</th><th>Oldest</th></tr></thead><tbody>${rows.map(([o,cs])=>{const od=cs.filter(c=>c.due&&new Date(c.due)<now).length,hi=cs.filter(c=>c.pri==="high").length,old=Math.max(...cs.map(c=>(Date.now()-(c.ts||Date.now()))/36e5));return `<tr><td><b>${esc(o)}</b></td><td>${cs.length}</td><td>${od?`<span class="tag bad">${od}</span>`:"0"}</td><td>${hi}</td><td class="sm">${old<48?Math.round(old)+" h":Math.round(old/24)+" d"}</td></tr><tr><td colspan="5" class="sm mut" style="padding-top:0">${cs.slice(0,4).map(c=>esc(c.t)).join(" · ")}${cs.length>4?" …":""}</td></tr>`}).join("")}</tbody></table>`:'<p class="mut sm">No open cards.</p>'}<a class="btn ghost sm" href="#board">Open Handoff Board</a></div>`},()=>{}],
 ["pack","Prompt pack",()=>`<div class="card"><p class="sm">Every seat's dispatch prompt with today's dashboard context, in one Markdown file — paste a section into Claude (or the Command Deck) when you want that seat to work. Includes each seat's playbook and HALT rules.</p><div class="row" style="flex-wrap:wrap"><select id="ai_pk" style="max-width:260px"><option value="core">Core seats (Steve, Vanessa, ISA, executives, key reports)</option><option value="all">All ${AI_SEATS.length} seats</option></select><button class="btn" id="ai_pk_dl">Download .md</button><button class="btn ghost" id="ai_pk_cp">Copy</button></div><pre id="ai_pk_pv" class="sm" style="white-space:pre-wrap;max-height:50vh;overflow:auto;margin-top:8px"></pre></div>`,
  ()=>{const build=()=>{const all=$("#ai_pk").value==="all";const L=AI_SEATS.filter(s=>all||s.t!=="rep"||AI_PLAY[s.n]);return `# AI team prompt pack — ${btToday()}\n\nHALT (Steven only): ${AI_HALT.join("; ")}.\n\n`+L.map(s=>{const P=aiPlay(s);return `## ${s.n} — ${s.r}\n\n${aiPrompt(s,"")}\n${P?`\nPlaybook${P.own?"":" (inherits "+P.from+")"}: daily — ${P.p.daily.join("; ")}. Weekly — ${P.p.weekly.join("; ")}. Measured by — ${P.p.kpi.join("; ")}. Never — ${P.p.never.join("; ")}.\n`:""}`}).join("\n")};const draw=()=>{const m=build();$("#ai_pk_pv").textContent=m.slice(0,5000)+(m.length>5000?`\n… (${m.length.toLocaleString()} characters)`:"")};$("#ai_pk").onchange=draw;draw();$("#ai_pk_dl").onclick=()=>btSave(`ai-team-prompt-pack-${btToday()}.md`,build(),"text/markdown");$("#ai_pk_cp").onclick=()=>copy(build())}],
 ["cov","Coverage check",()=>{const wf=PB_WORKFLOWS.filter(w=>!aiWfOwn(w));const names=new Set(AI_SEATS.map(s=>s.n));const badOwn=AI_WF_OWN.filter(r=>!names.has(r[1])||!names.has(r[2]));const dash=AGENTS.filter(a=>!aiAgent2(a));const noPg=AI_SEATS.filter(s=>!aiPages(s).length);
   const row=(ok,t,d)=>`<tr><td>${ok?'<span class="tag ok">OK</span>':'<span class="tag bad">GAP</span>'}</td><td><b>${t}</b></td><td class="sm">${d}</td></tr>`;
   return `<div class="card"><table><tbody>${row(!wf.length,"Every Pabbly workflow has an owner seat",wf.length?wf.map(w=>w.id).join(", ")+" unowned":`${PB_WORKFLOWS.length} of ${PB_WORKFLOWS.length} owned`)}${row(!badOwn.length,"Owner seats exist in the org chart snapshot",badOwn.length?badOwn.map(r=>r[1]+"/"+r[2]).join(", "):"all owner names resolve")}${row(!noPg.length,"Every seat has a dashboard home page",noPg.length?noPg.length+" without":`${AI_SEATS.length} seats mapped`)}${row(!dash.length,"Every dashboard agent maps to an org-chart seat or is dashboard-only",dash.length?`${dash.length} dashboard-only agents (fine — they are the working agents, not seats): ${dash.map(a=>a.name).join("; ")}`:"all agents mapped")}</tbody></table><p class="sm mut">The Command Deck org chart can change after this snapshot. When you add or rename a seat there, tell me and I will refresh <code>aiteam.js</code> — the page cannot read the Command Deck's data live.</p></div><div class="card"><h4>Export the ownership map</h4><div class="row" style="flex-wrap:wrap"><button class="btn ghost sm" id="ai_ex_j">Copy as JSON</button><button class="btn ghost sm" id="ai_ex_m">Copy as Markdown (for Brain 6D)</button></div></div>`},
  ()=>{$("#ai_ex_j").onclick=()=>copy(JSON.stringify(AI_SEATS.map(s=>({seat:s.n,role:s.r,agent:s.a,reportsTo:s.b,lane:aiLane(s),workflows:aiPB(s).map(x=>x.w.id+":"+x.role),pages:aiPages(s)})),null,1));$("#ai_ex_m").onclick=()=>copy(aiTeamMd())}]
];omTabs("aitab","ai","org",tabs).run()}};
const aiAgent2=a=>AI_SEATS.some(s=>a.name===s.n||a.name.startsWith(s.n+" ·"))||/Seminar|Prospector|Referral|Recruiter|Refi|Market Intel|Tutor|Ops|Sentinel|Studio|Chief of Staff|Structurer|Analyzer|Simulator|Writer|Coach|Advisor|Analyst|Strategist|Librarian|Agent|Classifier|Desk|Curative|Clearer|Coordinator|Improvement|Watcher/.test(a.name);
function aiTeamMd(){let m=`---\ntitle: AI team ownership map\ngenerated: ${btToday()}\nsource: VANESSA dashboard (snapshot of Command Deck org chart)\ntags: [ai-team, org-chart, workflows]\n---\n# AI team ownership map\n\nSeats, who they report to, the Pabbly workflows they own, and where they work in the dashboard.\n\n`;AI_SEATS.forEach(s=>{const pb=aiPB(s);m+=`## ${s.n} — ${s.r}\n- Reports to: ${s.b}\n- Agent: ${s.a||"—"}\n- Output lane: ${aiLane(s)}\n${pb.length?"- Workflows: "+pb.map(x=>x.w.id+" "+x.w.name+" ("+x.role+")").join("; ")+"\n":""}- Dashboard pages: ${aiPages(s).map(btLabel).join(", ")}\n\n`});return m}

/* ---------- Broker Bridge ---------- */
const BT_STAGES={"New Lead":"New","Contacted":"New","Appointment Set":"New","Active Client":"New","Under Contract":"New","Closed":"New"};
function btParseCSV(t){const rows=[];let r=[],f="",q=false;for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else q=false}else f+=c}else if(c==='"')q=true;else if(c===","){r.push(f);f=""}else if(c==="\n"||c==="\r"){if(c==="\r"&&t[i+1]==="\n")i++;r.push(f);f="";if(r.some(x=>x!==""))rows.push(r);r=[]}else f+=c}r.push(f);if(r.some(x=>x!==""))rows.push(r);return rows}
function btRead(text){text=(text||"").trim();if(!text)return {err:"Nothing pasted yet."};if(text[0]==="{"){try{const S=JSON.parse(text);if(!S.people&&!S.deals)return {err:"That JSON has no people or deals — copy the whole broker-cc-v1 value."};return {kind:"json",source:S.source||"",exported:S.exported||"",people:S.people||[],deals:S.deals||[],tasks:S.tasks||[],agents:S.agents||[],listings:S.listings||[]}}catch(e){return {err:"Couldn't read that as JSON ("+e.message+")."}}}
 const rows=btParseCSV(text);const h=rows[0].map(x=>x.trim().toLowerCase());if(!h.includes("name"))return {err:"CSV needs a Name column (the broker dashboard's Contacts export has one)."};const ix=k=>h.indexOf(k);const g=(r,k)=>ix(k)<0?"":(r[ix(k)]||"").trim();return {kind:"csv",people:rows.slice(1).map(r=>({name:g(r,"name"),type:g(r,"type"),stage:g(r,"stage"),source:g(r,"source"),budget:+(g(r,"budget").replace(/[^0-9.]/g,""))||0,area:g(r,"area"),phone:g(r,"phone"),email:g(r,"email"),next:g(r,"next follow-up"),notes:g(r,"notes"),id:"csv:"+(g(r,"email")||g(r,"phone")||g(r,"name"))})).filter(p=>p.name),deals:[],tasks:[],agents:[],listings:[]}}
const btMile=d=>{const a=d.accept,coe=btAddD(a,d.coe||30);return [{k:"emd",t:"Earnest money deposit due",date:btAddBiz(a,d.emdDays||3),lane:"ISA / EA"},{k:"appr",t:"Appraisal contingency",date:btAddD(a,d.appr||17),lane:"ISA / EA"},{k:"loan",t:"Loan contingency",date:btAddD(a,d.loan||17),lane:"ISA / EA"},{k:"rem",t:"Contingency removal — last day",date:btAddD(a,d.rem||17),lane:"Steven decision"},{k:"coe",t:"Close of escrow (lender CTC/funding must beat this)",date:coe,lane:"Steven decision"}]};
const btKnown=()=>store.get("bridge_seen",{});
function btPlan(D,o){const seen=btKnown(),now=btToday(),out={leads:[],cards:[],alerts:[]};
 D.people.forEach(p=>{const buyer=!p.type||/buyer|both|investor/i.test(p.type);if(o.buyers&&!buyer)return;if(p.stage==="Closed"&&!o.closed)return;const id="p:"+(p.id||p.email||p.phone||p.name);const dup=seen[id]||store.get("ld_leads",[]).some(l=>(p.email&&l.email===p.email)||(p.phone&&l.phone===p.phone));out.leads.push({id,p,dup:!!dup,pre:p.pre!==undefined?p.pre:null})});
 if(o.deals)D.deals.filter(d=>d.status!=="Closed"&&d.accept).forEach(d=>btMile(d).filter(m=>o.ms.includes(m.k)&&btDiff(m.date,now)>=-1).forEach(m=>{const id=`d:${d.id}:${m.k}`;out.cards.push({id,dup:!!seen[id],t:`${d.client||"Client"} — ${m.t}`,detail:`${d.addr||""} · ${d.side||""} · $${Math.round(d.price||0).toLocaleString()} · date ${m.date} (from RPA acceptance ${d.accept}). Dates computed from the broker dashboard's day counts — verify against the signed RPA.`,lane:m.lane,due:m.date})}));
 if(o.tasks)D.tasks.filter(t=>!t.done&&t.title).forEach(t=>{const id="t:"+(t.id||t.title);out.cards.push({id,dup:!!seen[id],t:`[Broker task] ${t.title}`,detail:(t.ch?t.ch+" · ":"")+"from Broker Command Center",lane:"ISA / EA",due:t.due||now})});
 if(o.lic)D.agents.forEach(a=>[["exp","DRE license"],["eo","E&O policy"]].forEach(([k,lbl])=>{if(!a[k])return;const n=btDiff(a[k],now);if(n<=60){const id=`a:${a.id||a.name}:${k}`;out.alerts.push({id,dup:!!seen[id],t:`${a.name}: ${lbl} ${n<0?"EXPIRED "+(-n)+"d ago":"expires in "+n+"d"} (${a[k]})`,days:n})}}));
 return out}
function btApply(plan,o){const seen=btKnown(),L=store.get("ld_leads",[]),bt="b"+Date.now();let nl=0,nc=0,na=0;const names=[];
 plan.leads.filter(x=>!x.dup).forEach(x=>{const p=x.p,score=Math.min(99,45+(/Active|Appointment|Under/.test(p.stage||"")?20:0)+(p.pre?10:0)+(p.phone?5:0)+(p.email?5:0)),l={id:"l"+Date.now()+Math.floor(Math.random()*9999),ts:Date.now(),name:p.name,phone:p.phone||"",email:p.email||"",src:"Realtor/Broker dashboard ("+(p.source||"Other")+")",prog:p.budget?"Purchase":"Purchase",mil:"Unknown",tl:p.timeline||"",owner:"ISA",note:`From Broker Command Center · stage ${p.stage||"—"} · ${p.type||""} · ${p.area||""}${p.budget?" · budget $"+Math.round(p.budget).toLocaleString():""}${p.notes?" · "+p.notes:""}`,score,contacted:true,fromBroker:true,bridgeBatch:bt};L.push(l);seen[x.id]=bt;names.push(p.name);nl++;
  if(o.cardLeads&&/Appointment|Active|Under/.test(p.stage||""))boardAdd({t:`Pre-approval check — ${p.name}`,detail:`${p.stage} on the real estate side${p.pre?" (pre-approval noted)":""}. Confirm client consent to financing contact first. ${l.note}`,lane:"ISA / EA",owner:"ISA",pri:/Under/.test(p.stage||"")?"high":"normal",due:new Date(Date.now()+864e5).toISOString(),src:"BRK",batch:bt},false);
  try{pipeline["New"].unshift({n:p.name,p:"Purchase",v:p.budget?"$"+Math.round(p.budget/1000)+"K":"—",s:score})}catch(e){}
  if(o.fire)emit("lead.created",{name:p.name,phone:l.phone,email:l.email,source:l.src,program:"Purchase",score},{noLocal:true})});
 store.set("ld_leads",L);try{persist()}catch(e){}
 plan.cards.filter(x=>!x.dup).forEach(x=>{boardAdd({t:x.t,detail:x.detail,lane:x.lane,owner:x.lane==="Steven decision"?"Steven":"ISA",pri:btDiff(x.due,btToday())<=2?"high":"normal",due:new Date(x.due+"T17:00:00").toISOString(),src:"BRK",batch:bt},false);seen[x.id]=bt;nc++});
 plan.alerts.filter(x=>!x.dup).forEach(x=>{boardAdd({t:x.t,detail:"From Broker Command Center roster — DRE/E&O alert.",lane:"Steven decision",owner:"Steven",pri:x.days<=14?"high":"normal",due:new Date(Date.now()+864e5).toISOString(),src:"BRK",batch:bt},false);seen[x.id]=bt;na++;if(o.fire)emit("license.alert",{item:x.t,days:x.days},{noLocal:true})});
 store.set("bridge_seen",seen);const h=store.get("bridge_hist",[]);h.push({ts:Date.now(),id:bt,leads:nl,cards:nc,alerts:na,names,src:o.srcLabel||""});store.set("bridge_hist",h.slice(-30));return {nl,nc,na}}

function btUndo(id){const L=store.get("ld_leads",[]),keep=L.filter(l=>l.bridgeBatch!==id),gone=L.filter(l=>l.bridgeBatch===id);store.set("ld_leads",keep);store.set("board",boardCards().filter(c=>c.batch!==id));const seen=btKnown();Object.keys(seen).forEach(k=>{if(seen[k]===id)delete seen[k]});store.set("bridge_seen",seen);try{gone.forEach(l=>{const k=pipeline["New"].findIndex(x=>x.n===l.name);if(k>=0)pipeline["New"].splice(k,1)});persist()}catch(e){}const h=store.get("bridge_hist",[]).map(x=>x.id===id?Object.assign(x,{undone:Date.now()}):x);store.set("bridge_hist",h);return gone.length}
function btSnap(D){const now=btToday();store.set("bridge_snap",{at:Date.now(),source:D.source||D.kind,exported:D.exported||"",deals:D.deals.filter(d=>d.status!=="Closed"&&d.status!=="Cancelled"&&d.accept).map(d=>({id:d.id,addr:d.addr||"",client:d.client||"",side:d.side||"",price:d.price||0,accept:d.accept,coe:d.coe||30,ms:btMile(d).map(m=>Object.assign({},m,{done:!!(d.done&&d.done[m.k])}))}))})}
const btCdBy=coe=>{const d=new Date(coe+"T12:00:00");let c=0;while(c<3){d.setDate(d.getDate()-1);if(d.getDay()!==0)c++}return d.toISOString().slice(0,10)};

PAGE.bridge={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><div class="row" style="flex-wrap:wrap"><div class="sp"><h3 style="margin:0">Broker Bridge <span class="sub">Real Estate Broker Dashboard → mortgage side: leads, escrow deadlines, tasks, license alerts</span></h3><p class="sm mut" style="margin:6px 0 0"><b>Honest scope:</b> the two dashboards are separate artifacts with separate storage, and the viewer blocks them from talking to each other — so this is a <b>paste-in bridge</b>, not a live sync. You copy the broker dashboard's data (or its Contacts CSV), paste it here, review, and apply. Imports are de-duplicated, so you can re-paste weekly (or daily) without doubling anything.</p></div><a class="btn sm" target="_blank" rel="noopener" href="https://claude.ai/artifact/XFx2H7cf8mnS8e8hjFzxNg">Open Broker Dashboard ↗</a></div></div>${omTabs("bttab","bt","import",[]).wrap()}`,
mount(){let D=null;const tabs=[
 ["import","Import",()=>{const h=store.get("bridge_hist",[]),l=h[h.length-1];return `<div class="card"><h4>1 · Get the data out of the Broker Dashboard</h4><ol class="sm" style="margin:4px 0 0 18px"><li><b>Easiest (people only):</b> Broker Dashboard → Contacts → <b>Export CSV</b>, open the file, copy everything.</li><li><b>Everything (people, escrows, tasks, roster):</b> open the Broker Dashboard, open browser DevTools (F12) → Console, set the context dropdown to the artifact's frame, run <code>copy(localStorage.getItem('broker-cc-v1'))</code>. That copies one JSON blob.</li><li>Don't want to use the console? Ask me to add a <b>“Send to VANESSA”</b> copy button inside the Broker Dashboard — it's your artifact, so I'd republish it only after you say yes.</li></ol><button class="btn ghost sm" id="bt_snip">Copy the console command</button></div><div class="card"><h4>2 · Paste it here</h4><textarea id="bt_in" rows="7" style="width:100%" placeholder="Paste the Contacts CSV or the broker-cc-v1 JSON…"></textarea><div class="row" style="margin-top:6px;flex-wrap:wrap"><button class="btn" id="bt_go">Read &amp; preview</button>${l?`<span class="sm mut">Last import ${new Date(l.ts).toLocaleString()}: ${l.leads} leads · ${l.cards} cards · ${l.alerts} alerts</span>`:""}</div><div id="bt_msg" class="sm"></div></div><div id="bt_prev"></div>`},
  ()=>{$("#bt_snip").onclick=()=>copy("copy(localStorage.getItem('broker-cc-v1'))");
   $("#bt_go").onclick=()=>{D=btRead($("#bt_in").value);if(D.err){$("#bt_msg").innerHTML=`<span class="tag bad">${esc(D.err)}</span>`;$("#bt_prev").innerHTML="";return}
    $("#bt_msg").innerHTML=`<span class="tag ok">${D.source==="broker-command-center"?"From Broker Command Center"+(D.exported?" · exported "+new Date(D.exported).toLocaleString():"")+" — ":""}Read ${D.kind.toUpperCase()}: ${D.people.length} people · ${D.deals.length} escrows · ${D.tasks.length} tasks · ${D.agents.length} agents · ${D.listings.length} listings</span>`;
    $("#bt_prev").innerHTML=`<div class="card"><h4>3 · Choose what comes across</h4><div class="grid g2 sm"><div><label><input type="checkbox" id="o_buy" checked> Buyer / Both / Investor contacts only (sellers and renters aren't mortgage leads yet)</label><br><label><input type="checkbox" id="o_closed"> Include Closed contacts (past-client nurture)</label><br><label><input type="checkbox" id="o_cl" checked> Add a “pre-approval check” card for Appointment Set / Active / Under Contract</label><br><label><input type="checkbox" id="o_fire"> Fire Pabbly events (lead.created, license.alert) for new items</label></div><div>${D.kind==="json"?`<label><input type="checkbox" id="o_deals" checked> Escrow deadlines → Handoff Board</label> <span class="mut">(open escrows only)</span><br><span class="mut">Milestones:</span> ${[["emd","EMD"],["appr","Appraisal"],["loan","Loan contingency"],["rem","CR removal"],["coe","COE"]].map(m=>`<label style="margin-right:8px"><input type="checkbox" class="o_ms" value="${m[0]}" ${m[0]==="emd"?"":"checked"}> ${m[1]}</label>`).join("")}<br><label><input type="checkbox" id="o_tasks"> Broker open tasks → Handoff Board</label><br><label><input type="checkbox" id="o_lic" checked> Agent DRE license / E&amp;O alerts (≤ 60 days)</label>`:'<span class="mut">CSV carries contacts only. Paste the JSON to bring escrows, tasks and the roster.</span>'}</div></div><div class="row" style="margin-top:8px"><button class="btn ghost" id="bt_pv">Preview</button><button class="btn" id="bt_ap">Apply import</button></div><div id="bt_list"></div></div>`;
    const opts=()=>({buyers:$("#o_buy").checked,closed:$("#o_closed").checked,cardLeads:$("#o_cl").checked,fire:$("#o_fire").checked,deals:!!$("#o_deals")?.checked,ms:$$(".o_ms:checked").map(x=>x.value),tasks:!!$("#o_tasks")?.checked,lic:!!$("#o_lic")?.checked});
    const pv=()=>{const pl=btPlan(D,opts());const nw=a=>a.filter(x=>!x.dup).length;$("#bt_list").innerHTML=`<p class="sm"><b>${nw(pl.leads)}</b> new leads (${pl.leads.length-nw(pl.leads)} already here) · <b>${nw(pl.cards)}</b> new Handoff cards (${pl.cards.length-nw(pl.cards)} already imported) · <b>${nw(pl.alerts)}</b> new alerts</p><div style="overflow:auto;max-height:40vh"><table class="sm"><tbody>${pl.leads.slice(0,60).map(x=>`<tr><td>${x.dup?'<span class="tag">have</span>':'<span class="tag ok">new</span>'}</td><td>Lead</td><td>${esc(x.p.name)}</td><td>${esc(x.p.stage||"")}</td><td>${esc(x.p.phone||x.p.email||"")}</td></tr>`).join("")}${pl.cards.slice(0,80).map(x=>`<tr><td>${x.dup?'<span class="tag">have</span>':'<span class="tag ok">new</span>'}</td><td>Card</td><td colspan="3">${esc(x.t)} · <b>${x.due}</b> · ${esc(x.lane)}</td></tr>`).join("")}${pl.alerts.map(x=>`<tr><td>${x.dup?'<span class="tag">have</span>':'<span class="tag warn">alert</span>'}</td><td>License</td><td colspan="3">${esc(x.t)}</td></tr>`).join("")}</tbody></table></div>`;return pl};
    $("#bt_pv").onclick=pv;pv();
    $("#bt_ap").onclick=()=>{const o=opts();o.srcLabel=D.source==="broker-command-center"?"Send to VANESSA":D.kind.toUpperCase();if(D.kind==="json")btSnap(D);const r=btApply(btPlan(D,o),o);toast(`Imported ${r.nl} leads · ${r.nc} cards · ${r.na} alerts`);pv()}}}],
 ["esc","Escrow watch",()=>{const sn=store.get("bridge_snap",null);if(!sn||!sn.deals.length)return `<div class="card sm mut">No escrows imported yet. Use <b>Send to VANESSA</b> in the Broker Dashboard (or paste its JSON) on the Import tab.</div>`;const now=btToday();return `<div class="card sm mut">Snapshot from ${esc(sn.source)} ${sn.exported?"(exported "+new Date(sn.exported).toLocaleString()+")":""}, imported ${new Date(sn.at).toLocaleString()}. Dates come from the RPA day counts entered on the broker side — verify against the signed contract and counters.</div>${sn.deals.map((d,i)=>{const cd=btCdBy(btAddD(d.accept,d.coe));return `<div class="card"><h4 style="margin:0">${esc(d.client)} — ${esc(d.addr)} <span class="tag">${esc(d.side)}</span> <span class="sub">$${Math.round(d.price).toLocaleString()} · accepted ${d.accept}</span></h4><table class="sm" style="margin-top:6px"><tbody>${d.ms.map(m=>{const n=btDiff(m.date,now);return `<tr><td>${m.done?'<span class="tag ok">done</span>':n<0?'<span class="tag bad">past</span>':n<=3?'<span class="tag warn">'+n+' d</span>':'<span class="tag">'+n+' d</span>'}</td><td><b>${esc(m.t)}</b></td><td>${m.date}</td><td class="mut">${esc(m.lane)}</td></tr>`}).join("")}<tr><td><span class="tag">TRID</span></td><td><b>Closing Disclosure must be received by</b></td><td>${cd}</td><td class="mut">3 business days before COE (Sundays skipped; check federal holidays)</td></tr></tbody></table><div class="row" style="margin-top:6px;flex-wrap:wrap"><button class="btn ghost sm bt-lu" data-i="${i}">Copy lender update for the TC</button><button class="btn ghost sm bt-ex" data-i="${i}">Copy loan-contingency extension request</button></div></div>`}).join("")}`},
  ()=>{const sn=store.get("bridge_snap",{deals:[]});const ms=(d,k)=>(d.ms.find(m=>m.k===k)||{}).date||"—";$$(".bt-lu").forEach(b=>b.onclick=()=>{const d=sn.deals[+b.dataset.i];copy(`LENDER UPDATE — ${d.client} · ${d.addr}\nAppraisal contingency: ${ms(d,"appr")} — appraisal [ordered / received / value at or above price]\nLoan contingency: ${ms(d,"loan")} — file stage [submitted / conditional approval / clear to close]\nOutstanding conditions: [list]\nClosing Disclosure to be received by: ${btCdBy(ms(d,"coe"))}\nClose of escrow: ${ms(d,"coe")}\nNext step & owner: [ ]\n— Steven Shearrill, NMLS #____ (status update, not a commitment to lend)`)});$$(".bt-ex").forEach(b=>b.onclick=()=>{const d=sn.deals[+b.dataset.i];copy(`Hi — on ${d.addr} (${d.client}), the loan contingency is ${ms(d,"loan")}. The file is [status] and the remaining items are [conditions]. To protect the buyer, we're asking for a written extension of the loan contingency to [new date] before it expires. Close of escrow stays [unchanged / proposed new date]. I'll send written status every [day/two days] until clear to close. — Steven Shearrill, NMLS #____`)})}],
 ["hist","History & undo",()=>{const h=store.get("bridge_hist",[]).slice().reverse();return `<div class="card">${h.length?`<table><thead><tr><th>When</th><th>Source</th><th>Leads</th><th>Cards</th><th>Alerts</th><th></th></tr></thead><tbody>${h.map(x=>`<tr><td class="sm">${new Date(x.ts).toLocaleString()}</td><td class="sm">${esc(x.src||"")}</td><td>${x.leads}</td><td>${x.cards}</td><td>${x.alerts}</td><td>${x.undone?'<span class="tag">undone</span>':x.id?`<button class="btn ghost sm bt-un" data-id="${x.id}">Undo</button>`:""}</td></tr>`).join("")}</tbody></table><p class="sm mut">Undo removes that import's leads, Handoff cards and pipeline entries, and lets the same items import again. Pabbly events already fired can't be recalled.</p>`:'<p class="sm mut">No imports yet.</p>'}</div>`},
  ()=>{$$(".bt-un").forEach(b=>b.onclick=()=>{const n=btUndo(b.dataset.id);toast(`Undone — ${n} leads removed`);const t=$("#bt_tabs button[data-t=hist]");t&&t.click()})}],
 ["scr","Scripts",()=>{const L=(typeof SCRIPTS!=="undefined"?SCRIPTS:[]).filter(x=>["Realtor bridge","Escrow deadlines","Agent","Partner","Referral partners"].includes(x.cat));return `<div class="card"><p class="sm">Talk tracks for the real-estate ↔ mortgage handoff: Realtor partners, escrow deadlines, co-marketing. Full library on the <a href="#scripts">Script library</a> page.</p>${L.length?L.map(x=>`<details class="acc"><summary><b>${esc(x.id)}</b> ${esc(x.t)} <span class="tag">${esc(x.cat)}</span></summary><div class="sm" style="white-space:pre-wrap;background:var(--bg2);padding:8px;border-radius:8px">${esc(x.script)}</div><p class="sm"><b>Next:</b> ${esc(x.next)} · <b>Compliance:</b> ${esc(x.compliance)}</p></details>`).join(""):'<p class="sm mut">No bridge scripts loaded.</p>'}</div>`},()=>{}],
 ["map","What maps where",()=>`<div class="card"><table><thead><tr><th>Broker Dashboard</th><th>VANESSA</th><th>Owner seat</th></tr></thead><tbody>
<tr><td>Contacts (Buyer / Both / Investor)</td><td>Speed-to-Lead list + Pipeline “New” + optional <b>Pre-approval check</b> card (marked contacted so the 5-minute alarm doesn't misfire)</td><td>Mateo · Kenji · ISA/EA</td></tr>
<tr><td>Escrow: EMD, appraisal, loan contingency, CR removal, COE</td><td>Handoff Board cards due on the date (computed from acceptance date + the day counts you set; verify against the signed RPA). Loan/appraisal → ISA/EA, CR removal &amp; COE → Steven</td><td>Carmen (TC) · Denise · Colette</td></tr>
<tr><td>Open tasks</td><td>Handoff Board (ISA / EA lane), tagged “Broker task”</td><td>Orca (dispatch)</td></tr>
<tr><td>Agent roster: DRE license &amp; E&amp;O expiry</td><td>Steven-decision card + <code>license.alert</code> (PB12) when ≤ 60 days</td><td>Beatrice · Clay · Alexandra</td></tr>
<tr><td>Listings, vendors, expenses, farms</td><td>Not imported — no mortgage action attached</td><td>—</td></tr>
<tr><td>Closed escrows / Closed contacts</td><td>Optional: past-client list for the Annual Mortgage Review and referral thank-yous</td><td>Thea · Wren</td></tr></tbody></table><p class="sm mut"><b>Compliance:</b> a Realtor-side client is not automatically a lender lead. Get the client's consent before financing outreach, and if you refer them to a lender you're affiliated with, the RESPA affiliated-business-arrangement disclosure applies. Never tie a referral to settlement-service kickbacks (RESPA §8).</p></div>`,()=>{}],
 ["out","Back to the broker side",()=>`<div class="card"><h4>Pre-approved / in-process buyers → CSV for the real estate side</h4><p class="sm">Exports this dashboard's leads in the same column layout the Broker Dashboard's Contacts export uses, so you can match them against your pipeline there. (I haven't confirmed the Broker Dashboard has a CSV <i>import</i>; if it doesn't, use it as a reference list or ask me to add one.)</p><button class="btn" id="bt_out">Download vanessa-leads.csv</button> <span class="sm mut" id="bt_outn"></span></div><div class="card"><h4>Closing-date feed (what the broker side needs from the lender)</h4><p class="sm">Copy a plain-text update for the Realtor/TC: file stage, appraisal status, CTC target and COE.</p><button class="btn ghost sm" id="bt_upd">Copy lender update template</button></div>`,
  ()=>{$("#bt_out").onclick=()=>{const L=store.get("ld_leads",[]);const q=v=>'"'+String(v??"").replace(/"/g,'""')+'"';const rows=[["Name","Type","Stage","Source","Budget","Area","Phone","Email","Score","Last contact","Next follow-up","Notes"],...L.map(l=>[l.name,"Buyer",l.contacted?"Contacted":"New Lead",l.src,"","",l.phone,l.email,l.score,"","",l.note])];btSave("vanessa-leads.csv",rows.map(r=>r.map(q).join(",")).join("\n"),"text/csv");$("#bt_outn").textContent=L.length+" leads"};
   $("#bt_upd").onclick=()=>copy(`LENDER UPDATE — [Client] · [Property]\nFile stage: [Submitted / Conditional / CTC]\nAppraisal: [ordered / received / value OK]\nOutstanding conditions: [list]\nTarget CTC: [date]  ·  COE: [date]\nNext step & owner: [ ]\n— Steven Shearrill, NMLS #____ (draft for TC; not a commitment to lend)`)}]
];omTabs("bttab","bt","import",tabs).run()}};

/* ---------- Brain 6D ---------- */
const BR_URL="https://claude.ai/artifact/VoWHW4YuKUCyNqGZMikEv8";
const brTerms=q=>q.toLowerCase().split(/[^a-z0-9$%.]+/).filter(w=>w.length>2);
function brSearch(q){const T=brTerms(q);if(!T.length)return [];return coachCorpus().map(c=>{const s=(c.src+" "+c.t).toLowerCase();const sc=T.reduce((a,t)=>a+(s.includes(t)?1:0)+(c.src.toLowerCase().includes(t)?1:0),0);return {c,sc}}).filter(x=>x.sc>0).sort((a,b)=>b.sc-a.sc).slice(0,8)}
const brQ=[["VA IRRRL net tangible benefit rules","Seasoning, recoupment and fee limits before quoting"],["VA residual income table for my region","Family size and loan amount"],["Who owns the 5-minute lead response SLA?","Roles and escalation"],["TRID 3-day CD timeline and re-disclosure triggers","Closing clock"],["Which seat handles appraisal value disputes?","Roland / Imani routing"],["Last time we changed the lock policy — why?","Decision history"],["Pabbly webhook failure recovery steps","Ops runbook"],["Zoho lead status definitions","CRM hygiene"],["ARIVE submission checklist","Processing"],["Realtor partner co-marketing rules (RESPA §8)","Partner compliance"],["Affiliated business disclosure when I'm agent and lender","Dual role"],["HELOC vs HELOAN vs cash-out talk track","Equity"],["HECM counseling and non-borrowing spouse rules","Reverse"],["Seller concessions to buydown — limits by program","Concessions"],["DSCR lender matrix notes","Investors"],["New-state licensing checklist (IL, NV, FL, AZ)","Expansion"],["Military PCS buyer timeline","Military"],["BAH qualifying notes","Military"],["Wire-fraud response steps","Security"],["Annual mortgage review agenda","Past clients"],["Weekly ops review template","Operating rhythm"],["Which workflows fire on loan funded?","Automations"],["Escrow deadline extension request wording","Realtor bridge"],["My best objection handles for rate shoppers","Scripts"]];
const brNotes=()=>store.get("brain_notes",[]);
function brMd(sel){const d=btToday();let m="";if(sel.team)m+=aiTeamMd()+"\n";
 if(sel.wf)m+=`---\ntitle: Pabbly workflow catalog (PB01–PB${PB_WORKFLOWS.length})\ngenerated: ${d}\ntags: [workflows, pabbly, sop]\n---\n# Workflow catalog\n\n`+PB_WORKFLOWS.map(w=>{const o=aiWfOwn(w);return `## ${w.id} ${w.name}\n- Event: ${w.event} · SLA: ${w.sla}\n- Owner: ${o?o.p+" (backup "+o.b+")":"unowned"}\n- What: ${w.what}\n- Steps: ${w.steps.join(" → ")}\n- AI: ${w.ai}\n- ISA/EA: ${w.isa}\n- Steven: ${w.steven}\n`}).join("\n")+"\n";
 if(sel.ex){const E=store.get("lb_ex",[]);m+=`---\ntitle: My guideline excerpts\ngenerated: ${d}\ntags: [guidelines, excerpts]\n---\n# My dated guideline excerpts\n\n`+(E.length?E.map(x=>`## ${(lbG(x.g)||{n:x.g}).n} ${x.s||""} (${x.d})\n${x.x}\n`).join("\n"):"_None saved yet._\n")+"\n"}
  if(sel.scripts&&typeof SCRIPTS!=="undefined")m+=`---\ntitle: Script library (${SCRIPTS.length} talk tracks)\ngenerated: ${d}\ntags: [scripts, talk-tracks, objections]\n---\n# Script library\n\n`+SCRIPTS.map(x=>`## ${x.id} ${x.t} (${x.cat})\n- When: ${x.when}\n- Goal: ${x.goal}\n\n${x.script}\n\n${(x.objections||[]).map(o=>`- **${o[0]}** → ${o[1]}`).join("\n")}\n\n- Next: ${x.next}\n- Compliance: ${x.compliance}\n`).join("\n")+"\n";
 if(sel.guides&&typeof LIB_GUIDES!=="undefined")m+=`---\ntitle: Official guideline sources\ngenerated: ${d}\ntags: [guidelines, sources]\n---\n# Official guideline sources\n\n`+LIB_GUIDES.map(g=>`- **${g.n}** (${g.cat}) — ${g.pub}. ${g.cov} Updates: ${g.cad}. Source: ${g.url}`).join("\n")+"\n\n";
 if(sel.ops)m+=`---\ntitle: Operating rhythm, escalation and HALT list\ngenerated: ${d}\ntags: [operations, ai-team, escalation]\n---\n# Operating rhythm\n\n`+AI_RHYTHM.map(r=>`- ${r[0]} — ${r[1]}: ${r[2]} (${r[3]})`).join("\n")+`\n\n# Escalation ladder\n\n`+AI_ESCALATE.map(e=>`- ${e[0]} → ${e[1]} (within ${e[2]})`).join("\n")+`\n\n# HALT list (Steven only)\n\n`+AI_HALT.map(h=>"- "+h).join("\n")+"\n\n";
 if(sel.bridge){const sn=store.get("bridge_snap",null),h=store.get("bridge_hist",[]);m+=`---\ntitle: Broker bridge log\ngenerated: ${d}\ntags: [broker-bridge, escrows]\n---\n# Broker bridge\n\n`+(h.length?h.map(x=>`- ${new Date(x.ts).toISOString().slice(0,10)} ${x.src||""}: ${x.leads} leads, ${x.cards} cards, ${x.alerts} alerts${x.undone?" (undone)":""}`).join("\n"):"_No imports yet._")+"\n\n"+(sn?sn.deals.map(x=>`## ${x.client} — ${x.addr}\n`+x.ms.map(m=>`- ${m.date}: ${m.t}${m.done?" (done)":""}`).join("\n")).join("\n\n"):"")+"\n\n"}
 if(sel.board){const B=boardCards();m+=`---\ntitle: Handoff board snapshot\ngenerated: ${d}\ntags: [handoff, board]\n---\n# Handoff board ${d}\n\n`+B.slice(0,200).map(c=>`- [${c.lane}] ${c.t} — owner ${c.owner||"—"}${c.due?" — due "+c.due.slice(0,10):""}${c.src?" ("+c.src+")":""}`).join("\n")+"\n\n"}
 if(sel.notes){const N=brNotes();m+=`---\ntitle: Dashboard decisions and lessons\ngenerated: ${d}\ntags: [decisions, lessons]\n---\n# Decisions & lessons\n\n`+(N.length?N.map(n=>`## ${n.d} · ${n.k}${n.seat?" · "+n.seat:""}\n${n.t}\n`).join("\n"):"_None captured yet._\n")+"\n"}
 return m}
PAGE.brain={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><div class="row" style="flex-wrap:wrap"><div class="sp"><h3 style="margin:0">Brain 6D link <span class="sub">your 2nd brain ↔ this dashboard: ask, send, capture</span></h3><p class="sm mut" style="margin:6px 0 0"><b>Honest scope:</b> Brain 6D is a published snapshot (a 3D map and term-index of ${"125"} files / ~1,071 sections), a separate artifact. It can't read this dashboard and this dashboard can't write into it. What this page does: (1) searches the dashboard's own knowledge first, (2) builds the exact recall question/command for your brain, (3) packages this dashboard's SOPs, workflows, AI-team map, excerpts, board and decisions as <b>brain-ready Markdown</b> you file into the brain's folder and re-index, and (4) captures decisions/lessons as you work so they make it there.</p></div><a class="btn sm" href="#mt_sb">Open Brain 6D here</a> <a class="btn ghost sm" target="_blank" rel="noopener" href="${BR_URL}">New tab ↗</a></div></div>${omTabs("brtab","br","ask",[]).wrap()}`,
mount(){const tabs=[
 ["ask","Ask",()=>`<div class="card"><input id="br_q" placeholder="What do you need to find? (e.g. IRRRL recoupment, lock policy, who owns appraisal disputes)" style="width:100%"><div class="row" style="margin-top:6px;flex-wrap:wrap">${brQ.map((q,i)=>`<button class="btn ghost sm br-t" data-i="${i}" title="${esc(q[1])}">${esc(q[0])}</button>`).join("")}</div></div><div id="br_out"></div>`,
  ()=>{const run=()=>{const q=$("#br_q").value.trim();if(!q){$("#br_out").innerHTML="";return}const hits=brSearch(q);const cmd=`bin/brain recall "${q.replace(/"/g,'\\"')}"`;$("#br_out").innerHTML=`<div class="card"><h4>1 · This dashboard already knows</h4>${hits.length?hits.map(h=>`<div class="sm" style="margin:6px 0"><b>${esc(h.c.src)}</b><br>${esc(h.c.t.slice(0,260))}${h.c.t.length>260?"…":""}</div>`).join(""):'<span class="sm mut">No match in the dashboard\'s own guides, SOPs or notes.</span>'}</div><div class="card"><h4>2 · Ask the brain</h4><p class="sm">Recall command (your brain's CLI):</p><pre class="sm" style="white-space:pre-wrap">${esc(cmd)}</pre><div class="row" style="flex-wrap:wrap"><button class="btn sm" id="br_c1">Copy recall command</button><button class="btn ghost sm" id="br_c2">Copy as a question for Claude</button><a class="btn ghost sm" href="#mt_sb">Open the brain map</a></div><p class="sm mut">In Brain 6D use “Ask the brain” with the same words; it ranks sections by term match, so use the specific nouns (program, form, seat name).</p></div>`;$("#br_c1").onclick=()=>copy(cmd);$("#br_c2").onclick=()=>copy(`Using my 2nd brain, answer from what is documented there (cite the file/section, say if it's stale or missing): ${q}`)};
   $("#br_q").oninput=run;$$(".br-t").forEach(b=>b.onclick=()=>{$("#br_q").value=brQ[+b.dataset.i][0];run()})}],
 ["send","Send to brain",()=>`<div class="card"><p class="sm">Pick what to package. Output is Markdown with front-matter (title, date, tags), one file per source so each lands as its own node in the brain.</p><div class="sm"><label><input type="checkbox" class="br-s" value="team" checked> AI team ownership map (${AI_SEATS.length} seats)</label><br><label><input type="checkbox" class="br-s" value="wf" checked> Workflow catalog PB01–PB${PB_WORKFLOWS.length} with owners and SLAs</label><br><label><input type="checkbox" class="br-s" value="ex" checked> My dated guideline excerpts (${store.get("lb_ex",[]).length})</label><br><label><input type="checkbox" class="br-s" value="notes" checked> Decisions &amp; lessons I captured (${brNotes().length})</label><br><label><input type="checkbox" class="br-s" value="board"> Handoff board snapshot (${boardCards().length} cards)</label><br><label><input type="checkbox" class="br-s" value="ops" checked> Operating rhythm, escalation ladder &amp; HALT list</label><br><label><input type="checkbox" class="br-s" value="scripts"> Script library (${typeof SCRIPTS!=="undefined"?SCRIPTS.length:0} talk tracks)</label><br><label><input type="checkbox" class="br-s" value="guides"> Official guideline sources (${typeof LIB_GUIDES!=="undefined"?LIB_GUIDES.length:0})</label><br><label><input type="checkbox" class="br-s" value="bridge"> Broker bridge log &amp; escrow snapshot</label></div><div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn" id="br_dl">Download .md</button><button class="btn ghost" id="br_cp">Copy Markdown</button></div><p class="sm mut">Then: save into the brain's source folder and re-run its index/build step, and Brain 6D will pick the new sections up on the next publish of the brain. (The dashboard can't trigger that for you.)</p></div><div class="card"><pre id="br_pv" class="sm" style="white-space:pre-wrap;max-height:40vh;overflow:auto"></pre></div>`,
  ()=>{const sel=()=>{const o={};$$(".br-s").forEach(c=>o[c.value]=c.checked);return o};const draw=()=>{const m=brMd(sel());$("#br_pv").textContent=m.slice(0,6000)+(m.length>6000?`\n\n… (${m.length.toLocaleString()} characters total)`:"")};$$(".br-s").forEach(c=>c.onchange=draw);draw();const mark=()=>{const E=store.get("brain_exp",{});Object.entries(sel()).forEach(([k,v])=>{if(v)E[k]=btToday()});store.set("brain_exp",E)};$("#br_dl").onclick=()=>{mark();btSave(`vanessa-dashboard-brain-${btToday()}.md`,brMd(sel()),"text/markdown")};$("#br_cp").onclick=()=>{mark();copy(brMd(sel()))}}],
 ["cap","Capture",()=>`<div class="card"><h4>Capture a decision or lesson</h4><div class="grid g2"><div><select id="br_k" style="width:100%">${["Decision","Lesson learned","SOP change","Lender quirk","Compliance note"].map(k=>`<option>${k}</option>`).join("")}</select><select id="br_seat" style="width:100%;margin-top:6px"><option value="">Seat (optional)</option>${AI_SEATS.filter(s=>s.t!=="rep").map(s=>`<option>${esc(s.n)}</option>`).join("")}</select></div><div><textarea id="br_t" rows="4" style="width:100%" placeholder="What happened, what you decided, why — written so you'd understand it in a year."></textarea></div></div><button class="btn" id="br_add">Save note</button></div><div id="br_list"></div>`,
  ()=>{const draw=()=>{const N=brNotes();$("#br_list").innerHTML=N.length?`<div class="card">${N.slice().reverse().map((n,i)=>`<div class="sm" style="margin:6px 0"><span class="tag">${esc(n.k)}</span> ${n.seat?`<span class="tag">${esc(n.seat)}</span> `:""}<span class="mut">${n.d}</span><br>${esc(n.t)} <button class="btn ghost sm br-x" data-i="${N.length-1-i}">✕</button></div>`).join("")}</div>`:'<div class="card sm mut">No notes yet.</div>';$$(".br-x").forEach(b=>b.onclick=()=>{const L=brNotes();L.splice(+b.dataset.i,1);store.set("brain_notes",L);draw()})};
   $("#br_add").onclick=()=>{const t=$("#br_t").value.trim();if(!t)return toast("Write the note first");const L=brNotes();L.push({d:btToday(),k:$("#br_k").value,seat:$("#br_seat").value,t});store.set("brain_notes",L);$("#br_t").value="";toast("Saved — it will go out with “Send to brain”");draw()};draw()}],
 ["dig","Weekly digest",()=>`<div class="card"><p class="sm">One Markdown note for the brain covering the last 7 days: decisions and lessons you captured, Handoff cards completed, broker-bridge imports and workflow events. File it weekly so the brain has the history, not just the rules.</p><div class="row"><button class="btn" id="br_dg_dl">Download digest</button><button class="btn ghost" id="br_dg_cp">Copy</button></div><pre id="br_dg" class="sm" style="white-space:pre-wrap;max-height:50vh;overflow:auto;margin-top:8px"></pre></div>`,
  ()=>{const since=Date.now()-7*864e5,d=btToday();const N=brNotes().filter(n=>new Date(n.d+"T12:00:00")>=since-864e5),B=boardCards().filter(c=>c.lane==="Done"&&(c.ts||0)>=since),H=store.get("bridge_hist",[]).filter(x=>x.ts>=since);let L=[];try{L=hubLog().filter(e=>e.ts>=since)}catch(e){}const by={};L.forEach(e=>{by[e.wf]=(by[e.wf]||0)+1});const m=`---\ntitle: Weekly digest ${d}\ngenerated: ${d}\ntags: [weekly-digest, decisions]\n---\n# Week ending ${d}\n\n## Decisions & lessons (${N.length})\n${N.map(n=>`- ${n.d} [${n.k}${n.seat?" · "+n.seat:""}] ${n.t}`).join("\n")||"- none captured"}\n\n## Handoff cards completed (${B.length})\n${B.slice(0,80).map(c=>`- ${c.t}${c.owner?" — "+c.owner:""}`).join("\n")||"- none"}\n\n## Broker bridge imports (${H.length})\n${H.map(x=>`- ${new Date(x.ts).toISOString().slice(0,10)}: ${x.leads} leads, ${x.cards} cards, ${x.alerts} alerts`).join("\n")||"- none"}\n\n## Workflow events (${L.length})\n${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`- ${k}: ${v}`).join("\n")||"- none"}\n`;$("#br_dg").textContent=m;$("#br_dg_dl").onclick=()=>btSave(`weekly-digest-${d}.md`,m,"text/markdown");$("#br_dg_cp").onclick=()=>copy(m)}],
 ["hyg","Brain hygiene",()=>{const E=store.get("brain_exp",{}),cad={team:30,wf:30,ex:7,notes:7,board:7,ops:30,scripts:30,guides:90,bridge:7};const nm={team:"AI team map",wf:"Workflow catalog",ex:"Guideline excerpts",notes:"Decisions & lessons",board:"Handoff board",ops:"Rhythm / escalation / HALT",scripts:"Script library",guides:"Guideline sources",bridge:"Broker bridge log"};return `<div class="card"><p class="sm">When each source last went to the brain from this browser, against a suggested cadence. Stale sources mean the brain answers from old rules.</p><table><thead><tr><th>Source</th><th>Last sent</th><th>Cadence</th><th>Status</th></tr></thead><tbody>${Object.keys(nm).map(k=>{const a=E[k]?btDiff(btToday(),E[k]):null;return `<tr><td><b>${nm[k]}</b></td><td class="sm">${E[k]||"never"}</td><td class="sm">every ${cad[k]} days</td><td>${a===null?'<span class="tag bad">never sent</span>':a>cad[k]?`<span class="tag warn">${a} days old</span>`:'<span class="tag ok">fresh</span>'}</td></tr>`}).join("")}</tbody></table></div><div class="card"><h4>Weekly brain routine (10 minutes, Friday)</h4><ol class="sm" style="margin:4px 0 0 18px"><li>Capture any decision from the week you haven't logged (Capture tab).</li><li>Download the Weekly digest and file it in the brain.</li><li>Re-send any source marked stale.</li><li>Re-run the brain's index/build step so Brain 6D picks the new sections up.</li><li>Ask the brain one question you answered this week — if it can't find it, the note is missing.</li></ol></div>`},()=>{}],
];omTabs("brtab","br","ask",tabs).run()}};

/* ---------- nav, search, coach ---------- */
{if(!PAGES.some(p=>p[0]==="AI Team & Bridges")){const i=PAGES.findIndex(p=>p[0]==="My Tools");const g=["AI Team & Bridges",[["aiteam","AI Team Bridge"],["bridge","Broker Bridge"],["brain","Brain 6D link"]]];if(i<0)PAGES.push(g);else PAGES.splice(i,0,g)}}
{const c0=coachCorpus;coachCorpus=function(){const out=c0();AI_SEATS.filter(s=>s.t!=="rep"||aiPB(s).length).forEach(s=>out.push({src:`AI team — ${s.n}`,t:`${s.r}. Reports to ${s.b}. Agent ${s.a||"—"}. Owns ${aiPB(s).map(x=>x.w.id+" "+x.w.name).join("; ")||"no workflows directly"}. Works in ${aiPages(s).map(btLabel).join(", ")}.`}));PB_WORKFLOWS.forEach(w=>{const o=aiWfOwn(w);if(o)out.push({src:`Workflow owner — ${w.id}`,t:`${w.name}: primary seat ${o.p}, backup ${o.b}. ${o.why}.`})});Object.entries(AI_PLAY).forEach(([n,P])=>out.push({src:`AI team — ${n} playbook`,t:`Daily: ${P.daily.join("; ")}. Weekly: ${P.weekly.join("; ")}. Measured by: ${P.kpi.join("; ")}. Never: ${P.never.join("; ")}.`}));out.push({src:"AI team — HALT list",t:"Steven only, never delegated: "+AI_HALT.join("; ")});AI_ESCALATE.forEach(e=>out.push({src:"AI team — escalation: "+e[0],t:`Route: ${e[1]}. Within: ${e[2]}.`}));out.push({src:"Broker Bridge",t:"Paste the Real Estate Broker Dashboard's Contacts CSV or broker-cc-v1 JSON to import buyer leads, escrow deadlines (EMD, appraisal, loan contingency, CR, COE), tasks and DRE/E&O alerts onto the Handoff Board."});return out}}
if(typeof SEARCH_ROUTES!=="undefined"){SEARCH_ROUTES.unshift([/^AI team — |^Workflow owner — /,{hash:"aiteam"}]);SEARCH_ROUTES.unshift([/^Broker Bridge/,{hash:"bridge"}])}
